import RNA, random, sys, time
import itertools

TARGET = open('/tmp/gladius_target.txt').read().strip()
N = len(TARGET)

# set up folding params
md = RNA.md()
md.dangles = 2
md.temperature = 37.0
# turner2004 is default

# precompute pair constraints from target: positions that must be paired/unpaired
# We'll use a permissive design approach: GA with target-structure-matching fitness.

pairs = []  # list of (i,j) base pairs in target
stack = []
for i,c in enumerate(TARGET):
    if c=='(':
        stack.append(i)
    elif c==')':
        j=stack.pop()
        pairs.append((j,i))
paired_pos = set()
for (i,j) in pairs:
    paired_pos.add(i); paired_pos.add(j)

ALLOWED = {'A':('U',), 'C':('G',), 'G':('C','U'), 'U':('A','G')}
COMP = {'A':'U','U':'A','C':'G','G':'C'}

def random_seq():
    s=['A']*N
    for (i,j) in pairs:
        # choose pair type
        ptype=random.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
        s[i]=ptype[0]; s[j]=ptype[1]
    return ''.join(s)

def fold(seq):
    fc=RNA.fold_compound(seq, md)
    e,struct=fc.mfe()
    return struct,e

def bp_distance(s):
    # count mismatched base pairs vs target using target pair set
    # compute pairs in s
    st=[]
    spairs=set()
    for i,c in enumerate(s):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop()
            spairs.add((j,i))
    tpairs=set(pairs)
    return len(tpairs.symmetric_difference(spairs))

def score(seq):
    struct,e = fold(seq)
    # bp distance
    st=[]
    spairs=set()
    for i,c in enumerate(struct):
        if c=='(':
            st.append(i)
        elif c==')':
            j=st.pop()
            spairs.add((j,i))
    tpairs=set(pairs)
    d=len(tpairs.symmetric_difference(spairs))
    return d,struct,e

def mutate(seq, rate=0.05):
    s=list(seq)
    for (i,j) in pairs:
        if random.random()<rate:
            ptype=random.choice([('G','C'),('C','G'),('A','U'),('U','A'),('G','U'),('U','G')])
            s[i]=ptype[0]; s[j]=ptype[1]
    # mutate unpaired positions
    for k in range(N):
        if k not in paired_pos and random.random()<rate*0.5:
            s[k]=random.choice('ACGU')
    return ''.join(s)

def anneal(seq, iters=4000, T0=2.0, seed=0):
    random.seed(seed)
    cur_d,_,_ = score(seq)
    best=seq; best_d=cur_d
    T=T0
    for it in range(iters):
        cand=mutate(seq, rate=0.04 + 0.06*(1-it/iters))
        cd,_,_=score(cand)
        if cd<=cur_d or random.random()<__import__('math').exp(-(cd-cur_d)/max(T,1e-6)):
            seq=cand; cur_d=cd
            if cd<best_d:
                best=cand; best_d=cd
                if best_d==0:
                    return best,0
        T=T0*(0.995**it)
    return best,best_d

if __name__=='__main__':
    tstart=time.time()
    best_overall=None; best_overall_d=10**9
    nrestarts=int(sys.argv[1]) if len(sys.argv)>1 else 8
    iters=int(sys.argv[2]) if len(sys.argv)>2 else 3000
    for r in range(nrestarts):
        seed=r
        random.seed(seed)
        s=random_seq()
        b,d=anneal(s,iters=iters,seed=seed)
        if d<best_overall_d:
            best_overall=b; best_overall_d=d
            print(f'restart {r} d={d} t={time.time()-tstart:.1f}',flush=True)
        if best_overall_d==0:
            break
    print('BEST_D',best_overall_d)
